INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000001'::uuid, 'banner'::character varying(50), 'Săn voucher hot tại Asa - Tiết kiệm mỗi ngày'::character varying(255), '<p><em>Khám phá hàng trăm voucher ăn uống, giải trí, du lịch và mua sắm từ các thương hiệu nổi bật trên ASA Voucher.</em></p>'::text, 'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=1600&q=85'::character varying(500), 'active'::character varying(20), '1'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-26 09:20:10.442+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000002'::uuid, 'banner'::character varying(50), 'Ăn ngon hơn - Chi ít hơn'::character varying(255), '<p>Ưu đãi hấp dẫn từ Highlands Coffee, Phúc Long, Pizza Hut, GoGi House và nhiều thương hiệu khác.</p>'::text, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=1600&q=85'::character varying(500), 'active'::character varying(20), '3'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-26 09:17:30.462+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000004'::uuid, 'popup'::character varying(50), 'Ưu đãi thành viên mới'::character varying(255), '<p><strong>Chào mừng bạn đến với ASA Voucher!</strong></p><p>Khám phá các voucher nổi bật và nhận ưu đãi dành riêng cho tài khoản mới.</p>'::text, 'https://images.unsplash.com/photo-1607083206869-4c7672e72a8a?w=1200&q=85'::character varying(500), 'active'::character varying(20), '1'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000005'::uuid, 'popup'::character varying(50), 'Flash Sale cuối tuần'::character varying(255), '<p>Voucher ăn uống và giải trí giảm giá hấp dẫn trong thời gian giới hạn. Số lượng có hạn.</p>'::text, 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1200&q=85'::character varying(500), 'active'::character varying(20), '2'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000003'::uuid, 'banner'::character varying(50), 'Voucher du lịch - Nghỉ dưỡng đáng giá'::character varying(255), '<p>Lên kế hoạch cho kỳ nghỉ với các voucher lưu trú, spa và ẩm thực tại những điểm đến được yêu thích.</p>'::text, 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1600&q=85'::character varying(500), 'active'::character varying(20), '2'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-26 09:17:43.955+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000006'::uuid, 'popup'::character varying(50), 'Đi chơi cuối tuần cùng ASA'::character varying(255), '<p>Tìm voucher xem phim, ăn uống và nghỉ dưỡng phù hợp cho kế hoạch cuối tuần của bạn.</p>'::text, 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=1200&q=85'::character varying(500), 'active'::character varying(20), '3'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000007'::uuid, 'article'::character varying(50), 'Voucher điện tử là gì và sử dụng như thế nào?'::character varying(255), '<p><strong>Voucher điện tử</strong> là phiếu ưu đãi được phát hành dưới dạng mã hoặc mã QR thay vì phiếu giấy.</p><p>Sau khi mua voucher trên ASA, khách hàng có thể xem thông tin voucher trong tài khoản và sử dụng theo hướng dẫn của từng đối tác.</p><h3>Cách sử dụng cơ bản</h3><ol><li>Kiểm tra thời hạn và điều kiện áp dụng.</li><li>Đến cửa hàng hoặc dịch vụ thuộc phạm vi áp dụng.</li><li>Xuất trình mã voucher trước khi thanh toán.</li><li>Kiểm tra trạng thái voucher sau khi sử dụng.</li></ol>'::text, 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1400&q=85'::character varying(500), 'active'::character varying(20), '1'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000008'::uuid, 'article'::character varying(50), '5 lưu ý trước khi mua voucher online'::character varying(255), '<p>Mua voucher online giúp tiết kiệm chi phí, nhưng bạn nên đọc kỹ thông tin trước khi thanh toán.</p><h3>1. Kiểm tra thời hạn sử dụng</h3><p>Hãy chắc chắn voucher còn đủ thời gian để bạn sử dụng.</p><h3>2. Xem phạm vi áp dụng</h3><p>Một số voucher chỉ áp dụng tại một số tỉnh, thành phố hoặc chi nhánh nhất định.</p><h3>3. Đọc điều kiện sử dụng</h3><p>Kiểm tra phụ thu, ngày không áp dụng và khả năng kết hợp với chương trình khác.</p><h3>4. Xem giá trị thực tế</h3><p>So sánh giá bán voucher với giá trị sản phẩm hoặc dịch vụ.</p><h3>5. Bảo mật mã voucher</h3><p>Không chia sẻ mã voucher công khai trước khi sử dụng.</p>'::text, 'https://images.unsplash.com/photo-1556742111-a301076d9d18?w=1400&q=85'::character varying(500), 'active'::character varying(20), '2'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000009'::uuid, 'article'::character varying(50), 'Gợi ý voucher ăn uống cho cuối tuần'::character varying(255), '<p>Một buổi gặp gỡ cuối tuần có thể tiết kiệm hơn khi bạn chuẩn bị voucher trước.</p><p>ASA Voucher cung cấp nhiều lựa chọn từ cà phê, trà sữa, pizza đến buffet nướng. Bạn có thể lọc voucher theo thương hiệu, mức giá và khu vực để tìm ưu đãi phù hợp.</p><p>Trước khi mua, hãy kiểm tra số lượng còn lại, ngày hết hạn và chi nhánh áp dụng.</p>'::text, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=1400&q=85'::character varying(500), 'active'::character varying(20), '3'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000010'::uuid, 'article'::character varying(50), 'Cách chọn voucher xem phim tiết kiệm'::character varying(255), '<p>Voucher xem phim phù hợp cho khách hàng muốn chủ động lên kế hoạch giải trí nhưng vẫn kiểm soát ngân sách.</p><p>Bạn nên kiểm tra định dạng phim được áp dụng, ngày trong tuần, rạp áp dụng và các khoản phụ thu nếu có. Với combo vé và bắp nước, hãy đọc kỹ thành phần combo trước khi mua.</p>'::text, 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=1400&q=85'::character varying(500), 'active'::character varying(20), '4'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000011'::uuid, 'article'::character varying(50), 'Kinh nghiệm sử dụng voucher nghỉ dưỡng'::character varying(255), '<p>Voucher nghỉ dưỡng thường có giá trị lớn và nhiều điều kiện hơn voucher ăn uống.</p><p>Trước khi mua, bạn nên kiểm tra thời gian đặt trước, giai đoạn cao điểm, phụ thu cuối tuần, loại phòng và số lượng khách được áp dụng.</p><p>Sau khi mua, hãy liên hệ đặt chỗ sớm và lưu lại thông tin xác nhận của đối tác.</p>'::text, 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1400&q=85'::character varying(500), 'active'::character varying(20), '5'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000012'::uuid, 'article'::character varying(50), 'Vì sao nên kiểm tra điều kiện voucher trước khi thanh toán?'::character varying(255), '<p>Mỗi voucher có thể có phạm vi sử dụng khác nhau. Một voucher giá tốt chưa chắc phù hợp nếu không sử dụng được tại địa điểm hoặc thời gian bạn mong muốn.</p><p>ASA hiển thị các thông tin quan trọng như thời gian bán, thời hạn sử dụng, khu vực áp dụng, số lượng còn lại và điều kiện sử dụng để khách hàng cân nhắc trước khi mua.</p>'::text, 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=1400&q=85'::character varying(500), 'active'::character varying(20), '6'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000013'::uuid, 'policy'::character varying(50), 'Chính sách mua và sử dụng voucher'::character varying(255), '<h3>1. Thông tin voucher</h3><p>Khách hàng có trách nhiệm kiểm tra tên voucher, đối tác cung cấp, giá bán, khu vực áp dụng, thời hạn và điều kiện sử dụng trước khi thanh toán.</p><h3>2. Sử dụng voucher</h3><p>Voucher chỉ được sử dụng theo đúng hướng dẫn và tại các địa điểm thuộc phạm vi áp dụng.</p><h3>3. Bảo mật mã voucher</h3><p>Khách hàng cần bảo mật mã voucher và không chia sẻ công khai. ASA không chịu trách nhiệm đối với trường hợp voucher bị sử dụng bởi người khác do khách hàng tự làm lộ mã.</p>'::text, 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=1400&q=85'::character varying(500), 'active'::character varying(20), '1'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000014'::uuid, 'policy'::character varying(50), 'Chính sách thanh toán'::character varying(255), '<p>ASA Voucher hỗ trợ các phương thức thanh toán được hiển thị tại bước thanh toán.</p><p>Khách hàng cần kiểm tra tổng giá trị đơn hàng trước khi xác nhận. Trường hợp giao dịch thanh toán không thành công, đơn hàng chỉ được ghi nhận hoàn tất khi hệ thống nhận được xác nhận thanh toán hợp lệ.</p><p>ASA không yêu cầu khách hàng cung cấp mật khẩu ngân hàng, mã PIN hoặc mã OTP ngoài giao diện thanh toán chính thức của đơn vị cung cấp dịch vụ thanh toán.</p>'::text, 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=1400&q=85'::character varying(500), 'active'::character varying(20), '2'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000015'::uuid, 'policy'::character varying(50), 'Chính sách hoàn tiền voucher'::character varying(255), '<p>Yêu cầu hoàn tiền được xem xét theo trạng thái voucher và điều kiện của từng sản phẩm.</p><p>Voucher đã được sử dụng hoặc đã hết hạn do khách hàng không sử dụng trong thời gian quy định có thể không đủ điều kiện hoàn tiền.</p><p>Nếu voucher không thể sử dụng do lỗi được xác nhận từ hệ thống hoặc đối tác, ASA sẽ kiểm tra giao dịch và hỗ trợ khách hàng theo quy trình xử lý khiếu nại.</p>'::text, 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=1400&q=85'::character varying(500), 'active'::character varying(20), '3'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
INSERT INTO public.cms_contents (id, content_type, title, content, image_url, status, sort_order, created_by, created_at, updated_at) VALUES ('63000000-0000-0000-0000-000000000016'::uuid, 'policy'::character varying(50), 'Chính sách bảo mật thông tin'::character varying(255), '<p>ASA thu thập và xử lý thông tin cần thiết để vận hành tài khoản, xử lý đơn hàng, hỗ trợ khách hàng và cải thiện chất lượng dịch vụ.</p><p>Thông tin cá nhân không được bán cho bên thứ ba. Một số dữ liệu có thể được chia sẻ với đối tác hoặc nhà cung cấp dịch vụ khi cần thiết để hoàn thành giao dịch hoặc tuân thủ yêu cầu pháp luật.</p><p>Khách hàng nên sử dụng mật khẩu mạnh và không chia sẻ thông tin đăng nhập với người khác.</p>'::text, 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=1400&q=85'::character varying(500), 'active'::character varying(20), '4'::integer, NULL, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone, '2026-08-25 18:39:25.104533+00'::timestamp(6) with time zone);
